package com.therighthon.rnr.common.recipe;
import net.minecraft.resources.ResourceLocation; import net.minecraft.world.Container; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.crafting.Recipe; import net.minecraft.world.level.Level; import net.minecraft.core.NonNullList; import net.minecraft.core.RegistryAccess;
public abstract class RNRSimpleBlockRecipe implements Recipe<Container>{protected final ResourceLocation id;protected final RNRBlockIngredient ingredient;protected final net.minecraft.world.level.block.state.BlockState outputState;protected RNRSimpleBlockRecipe(ResourceLocation i,RNRBlockIngredient in,net.minecraft.world.level.block.state.BlockState out){id=i;ingredient=in;outputState=out;} public boolean matchesBlock(net.minecraft.world.level.block.state.BlockState s){return ingredient.test(s);} public RNRBlockIngredient getBlockIngredient(){return ingredient;} public net.minecraft.world.level.block.state.BlockState getBlockCraftingResult(net.minecraft.world.level.block.state.BlockState s){return outputState;} public ResourceLocation getId(){return id;} public boolean canCraftInDimensions(int w,int h){return true;} public ItemStack getResultItem(RegistryAccess a){return ItemStack.EMPTY;} public ItemStack assemble(Container c,RegistryAccess a){return ItemStack.EMPTY;} public NonNullList<ItemStack> getRemainingItems(Container c){return NonNullList.withSize(c.getContainerSize(),ItemStack.EMPTY);} public boolean matches(Container c,Level l){return false;} public boolean isSpecial(){return true;} }
